import React, { useEffect, useState, useRef } from "react";
import axios from "axios";
import {
  MapContainer,
  TileLayer,
  Polyline,
  Marker,
  Tooltip
} from "react-leaflet";
import "leaflet/dist/leaflet.css";

import L from "leaflet";
import "leaflet-rotatedmarker";

import droneImg from "./x-drone.png";

import {
  Line
} from "react-chartjs-2";

import {
  Chart as ChartJS,
  LineElement,
  CategoryScale,
  LinearScale,
  PointElement,
  Legend
} from "chart.js";

ChartJS.register(LineElement, CategoryScale, LinearScale, PointElement, Legend);

// 🚁 DRONE ICON
const droneIcon = new L.Icon({
  iconUrl: droneImg,
  iconSize: [40, 40],
  iconAnchor: [20, 20]
});

function App() {
  const [data, setData] = useState([]);
  const [path, setPath] = useState([]);
  const [index, setIndex] = useState(0);
  const [playing, setPlaying] = useState(false);

  const mapRef = useRef();

  const [startTime, setStartTime] = useState("");
  const [endTime, setEndTime] = useState("");

  // 🧠 HEADING CALCULATION
  function getHeading(prev, curr) {
    if (!prev || !curr) return 0;

    const dy = curr.lat - prev.lat;
    const dx = curr.lng - prev.lng;

    return Math.atan2(dy, dx) * (180 / Math.PI);
  }

  // 🚀 FETCH DATA
  const fetchData = async () => {
    try {
      const res = await axios.get("http://localhost:3000/path", {
        params: {
          start: startTime,
          end: endTime
        }
      });

      const d = res.data;

      setData(d);
      setIndex(0);

      const coords = d.map(p => ({
        lat: p.location.coordinates[1],
        lng: p.location.coordinates[0],
        alt: p.alt || 0,
        voltage: p.voltage || 0
      }));

      setPath(coords);

      // 🔥 AUTO ZOOM
      if (coords.length > 0 && mapRef.current) {
        const bounds = coords.map(c => [c.lat, c.lng]);
        mapRef.current.fitBounds(bounds);
      }

    } catch (err) {
      console.error(err);
    }
  };

  // ▶ PLAY ANIMATION
  useEffect(() => {
    if (!playing) return;

    const interval = setInterval(() => {
      setIndex(prev => {
        if (prev >= path.length - 1) {
          clearInterval(interval);
          return prev;
        }
        return prev + 1;
      });
    }, 100);

    return () => clearInterval(interval);
  }, [playing, path]);

  // 📍 FOLLOW DRONE
  useEffect(() => {
    if (path[index] && mapRef.current) {
      mapRef.current.flyTo(
        [path[index].lat, path[index].lng],
        18,
        { duration: 0.5 }
      );
    }
  }, [index]);

  // 📊 GRAPH DATA
  const chartData = {
    labels: path.slice(0, index).map((_, i) => i),
    datasets: [
      {
        label: "Altitude (m)",
        data: path.slice(0, index).map(p => p.alt),
        borderColor: "cyan",
        backgroundColor: "rgba(0,255,255,0.2)",
        tension: 0.3
      },
      {
        label: "Battery (V)",
        data: path.slice(0, index).map(p => p.voltage),
        borderColor: "yellow",
        backgroundColor: "rgba(255,255,0,0.2)",
        tension: 0.3
      }
    ]
  };

  const chartOptions = {
    responsive: true,
    plugins: {
      legend: {
        labels: { color: "white" }
      }
    },
    scales: {
      x: {
        ticks: { color: "white" }
      },
      y: {
        ticks: { color: "white" }
      }
    }
  };

  return (
    <div style={{ background: "black", color: "white", height: "100vh" }}>
      <h2>🚁 Drone Timeline (Directional Playback)</h2>

      {/* ⏱ TIME FILTER */}
      <div>
        Start:
        <input
          type="datetime-local"
          value={startTime}
          onChange={e => setStartTime(e.target.value)}
        />

        End:
        <input
          type="datetime-local"
          value={endTime}
          onChange={e => setEndTime(e.target.value)}
        />

        <button onClick={fetchData}>Apply</button>
      </div>

      {/* ▶ CONTROLS */}
      <div>
        <button onClick={() => setPlaying(true)}>▶ Play</button>
        <button onClick={() => setPlaying(false)}>⏸ Pause</button>
      </div>

      {/* 🗺 MAP */}
      <MapContainer
        center={[12.97, 77.59]}
        zoom={13}
        style={{ height: "60vh" }}
        whenCreated={(map) => (mapRef.current = map)}
      >
        <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />

        {/* 🔵 PATH */}
        <Polyline
          positions={path.slice(0, index).map(p => [p.lat, p.lng])}
          color="cyan"
          weight={4}
        />

        {/* 🚁 DRONE MARKER WITH ROTATION */}
      // 🔵 CURRENT POINT (moving dot)
{path[index] && (
  <Marker
    position={[path[index].lat, path[index].lng]}
    icon={L.divIcon({
      className: "",
      html: `
        <div style="
          width: 14px;
          height: 14px;
          background: cyan;
          border-radius: 50%;
          border: 2px solid white;
          box-shadow: 0 0 10px cyan;
        "></div>
      `
    })}
  >
    <Tooltip>
      Alt: {path[index].alt} m <br />
      Battery: {path[index].voltage} V
    </Tooltip>
  </Marker>
)}
      </MapContainer>

      {/* 📊 GRAPH */}
      <div style={{ height: "30vh", background: "#111" }}>
        <Line data={chartData} options={chartOptions} />
      </div>
    </div>
  );
}

export default App;
